SELECT CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END AS start_cohort, SUM(CASE WHEN plan = 'standard' THEN 1 ELSE 0 END) AS standard_count FROM subscriptions WHERE customer_id IS NULL OR YEAR(end_date) = 2024 GROUP BY CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END
